  insert into pokemon_media(pokemon_id, silhouette_levels, updated_at) values (_id, _levels, now())
insert into public.pokemon_media (pokemon_id, description_parts) values
(1, $j$["Costuma ficar quieto ao sol, cochilando em clareiras tranquilas, e se apega rápido a quem cuida bem dele.", "Passa dias sem comer, vivendo da energia que acumula com a luz; quando ameaçado, chicoteia com cipós finos.", "É pequeno, anda de quatro e tem pele verde-azulada com manchas escuras, parecendo um sapinho.", "Nasce com uma semente grande presa às costas, que cresce junto com ele."]$j$::jsonb),
(2, $j$["Fica mais parado e pesado com o tempo, e prefere lugares abertos onde bate bastante sol.", "Dispara folhas afiadas como lâminas e usa cipós para agarrar e empurrar quem chega perto.", "Anda de quatro, é verde-azulado com manchas escuras e tem pernas mais firmes que antes.", "Leva nas costas um botão de flor rosado e fechado, prestes a desabrochar, que pesa cada vez mais."]$j$::jsonb),
(3, $j$["Vive calmo em campos ensolarados e outros bichos costumam descansar perto dele, atraídos pelo clima tranquilo.", "Depois de chuva forte, solta um perfume doce que acalma quem está por perto e atrai visitantes.", "É grande, pesado e anda de quatro, com pele verde-azulada e pernas grossas como troncos.", "Carrega nas costas uma enorme flor rosa aberta, com folhas largas, que se abre virada para o sol."]$j$::jsonb),
(4, $j$["Gosta de lugares quentes e secos e fica de mau humor em dias de chuva.", "É curioso e um pouco teimoso; quando se assusta, solta brasas pela boca para espantar quem o incomoda.", "Pequeno, anda em duas patas e tem a pele laranja com a barriga cor de creme.", "A ponta da cauda tem uma chama acesa que mostra a saúde dele: se apagar, ele corre perigo."]$j$::jsonb),
(5, $j$["Fica agressivo e briguento, vive procurando confusão em montanhas rochosas e quentes.", "Ataca com garras afiadas e golpes de cauda; quando se irrita, o ar em volta esquenta muito.", "Anda em duas patas, tem pele vermelho-escura e um chifre curvado para trás na cabeça.", "A chama da cauda fica azulada e mais forte quando ele luta, e ele ataca sem piedade."]$j$::jsonb),
(6, $j$["Voa alto procurando adversários fortes e só respeita quem consegue enfrentá-lo de igual para igual.", "Nunca ataca um oponente mais fraco; seu sopro é tão quente que derrete rochas.", "É grande, laranja, com pescoço comprido, dois chifres pequenos e grandes asas com o lado de dentro esverdeado.", "Parece um dragão alaranjado que cospe fogo e tem uma chama acesa na ponta da cauda."]$j$::jsonb),
(7, $j$["Vive perto de lagos e rios, nadando o dia inteiro, e adora brincar de molhar os outros.", "Quando se sente ameaçado, se esconde e depois solta jatos fortes de água pela boca.", "É pequeno, azul-claro, anda em duas patas e tem uma cauda enrolada.", "Tem um casco marrom nas costas onde recolhe o corpo inteiro para se proteger."]$j$::jsonb),
(8, $j$["Dizem que vive muitos e muitos anos e é visto como sinal de sorte por quem mora perto do mar.", "Nada rápido mexendo as orelhas, e esconde-se no casco quando atacado, contra-atacando com mordidas.", "É azul mais escuro, com orelhas grandes parecidas com asas e um casco marrom.", "Tem uma cauda branca e felpuda que parece uma nuvem, e pode ficar coberta de algas com a idade."]$j$::jsonb),
(9, $j$["É pesado e firme; prefere esperar parado e aguentar golpes antes de reagir com força.", "Joga o próprio peso contra os inimigos para derrubá-los e consegue acertar alvos de muito longe.", "Grande e azul, anda em duas patas e carrega um casco marrom grosso e duro.", "Tem dois canhões saindo do casco, nas costas, que disparam jatos de água poderosos."]$j$::jsonb),
(10, $j$["Vive em florestas, escondido entre as folhas, e come sem parar o dia todo.", "Para assustar quem o ataca, solta um cheiro forte; também solta fios de seda pela boca.", "É uma lagarta pequena e verde, com uma barriga amarelada e pés curtinhos.", "Tem uma antena vermelha em forma de forquilha na cabeça e olhos grandes desenhados nas laterais."]$j$::jsonb),
(11, $j$["Quase não se mexe e passa o tempo quieto, esperando uma mudança importante acontecer.", "Não consegue fugir nem atacar; sua única defesa é ficar duro como pedra.", "Tem o corpo verde, curvado e sem pernas, com olhos sonolentos.", "É um casulo verde de casca dura; por dentro, o corpo mole está se transformando."]$j$::jsonb),
(12, $j$["Voa por campos floridos durante o dia e encontra flores com néctar a quilômetros de distância.", "Bate as asas soltando um pó que pode envenenar, paralisar ou fazer dormir.", "Tem o corpo pequeno e roxo-azulado, olhos grandes e vermelhos e antenas finas.", "É uma borboleta de asas brancas com bordas pretas, cobertas de escamas de pó."]$j$::jsonb),
(13, $j$["Vive em florestas e matos, comendo folhas o dia inteiro e sempre escondido.", "Tem um olfato muito bom para achar suas folhas favoritas e se defende com um ferrão venenoso.", "É uma larva pequena, marrom-amarelada, com o nariz rosado e o corpo em gomos.", "Tem um ferrão afiado e venenoso na cabeça e outro na ponta da cauda."]$j$::jsonb),
(14, $j$["Fica quase sempre parado, pendurado em galhos, esperando o momento de mudar.", "Mesmo sem se mexer, pode soltar um ferrão venenoso quando alguém chega muito perto.", "É amarelo, sem braços nem pernas, e tem olhinhos atentos numa carapaça.", "É um casulo amarelo e duro em forma de cone, preso às árvores por fios."]$j$::jsonb),
(15, $j$["É extremamente territorial e ataca em grupo quem se aproxima do ninho.", "Voa muito rápido e furioso, e quem mexe com um deles costuma ser perseguido por um enxame.", "É um inseto amarelo e preto com listras no abdômen, asas transparentes e olhos vermelhos.", "Tem dois ferrões enormes nos braços e outro na ponta do corpo, como uma vespa gigante."]$j$::jsonb),
(16, $j$["É calmo, prefere fugir a brigar e vive comum em matas e campos.", "Come insetos e se defende levantando areia com as asas para atrapalhar o inimigo.", "É uma ave pequena, marrom, com barriga clara e bico curtinho.", "É o passarinho mais comum de todos: tem penas marrons e uma marca preta e creme ao redor dos olhos."]$j$::jsonb),
(17, $j$["Defende com força seu território e patrulha uma área grande durante o voo.", "Tem garras fortes para agarrar presas e as leva ao ninho voando de longe.", "Ave de tamanho médio, com penas marrons e uma crista vermelha e amarela no alto da cabeça.", "Tem uma vista tão boa que enxerga presas no chão enquanto voa muito alto."]$j$::jsonb),
(18, $j$["Voa por grandes distâncias com elegância e quase nunca é visto no chão.", "Bate as asas tão forte que dobra árvores, e mergulha rápido para pegar presas.", "Ave grande, marrom e creme, de bico afiado e porte imponente.", "Tem uma longa crista de penas vermelhas e amarelas que cai até as costas."]$j$::jsonb),
(19, $j$["Vive em qualquer lugar, das cidades aos campos, e se multiplica muito rápido.", "Rói praticamente tudo o que encontra, até fios e madeira, e é muito cauteloso.", "É pequeno, roxo, com barriga creme, bigodes e cauda enrolada.", "Tem dois dentes da frente enormes que crescem sem parar, por isso precisa roer o tempo todo."]$j$::jsonb),
(20, $j$["Fica em bandos perto de onde há comida e não desiste fácil de um alvo.", "Usa os dentes para roer pedras e troncos e nada bem quando precisa.", "Maior, marrom-alaranjado, com barriga creme, bigodes compridos e pés grandes.", "Tem dois dentes da frente imensos e fortes, capazes de roer concreto."]$j$::jsonb),
(21, $j$["É barulhento e esquentado, vive em campos abertos e defende seu espaço sem medo.", "Caça insetos no mato e grita alto para avisar os outros do bando de perigos.", "Ave pequena, marrom, com asas curtas e penas avermelhadas.", "Bate as asas curtinhas sem parar para conseguir voar e tem um bico curto e bravo."]$j$::jsonb),
(22, $j$["Consegue voar o dia inteiro sem descansar e vigia tudo do alto.", "Caça agarrando presas em pleno voo, usando um bico muito comprido.", "Ave grande, marrom, com asas largas e uma crista avermelhada.", "Tem um pescoço longo e um bico enorme e fino, perfeito para pegar presas de dentro da terra ou da água."]$j$::jsonb),
(23, $j$["Rasteja pelo mato em silêncio e se esconde enrolado no chão.", "Engole ovos de aves inteiros e balança a língua para sentir o ar.", "É uma serpente roxa, comprida, com barriga amarela e olhos amarelados.", "Tem um chocalho amarelo na ponta da cauda e o nome é uma palavra de trás para frente."]$j$::jsonb),
(24, $j$["Intimida qualquer um antes de lutar e vive em áreas de mato alto.", "Aperta os inimigos com o corpo forte e tem uma picada venenosa.", "É uma serpente grande e roxa, com barriga amarela e olhar ameaçador.", "Abre um capuz largo com um desenho que parece um rosto assustador para espantar quem chega."]$j$::jsonb),
(25, $j$["Vive em florestas, em grupos, e é curioso com pessoas, mas pode ser arisco no começo.", "Ao se sentir ameaçado, solta faíscas pelas bochechas; às vezes atrapalha aparelhos elétricos.", "É pequeno e amarelo, com orelhas compridas de pontas pretas e listras marrons nas costas.", "Tem bochechas vermelhas que soltam choque e uma cauda em forma de raio."]$j$::jsonb),
(26, $j$["Fica agitado e pode ser perigoso quando carregado de energia demais.", "Usa a cauda fincada no chão para soltar a energia de sobra que o corpo acumula.", "É laranja, com barriga clara, orelhas marrons e bochechas amarelas.", "Tem uma cauda longa e fina que termina num raio e solta descargas fortíssimas."]$j$::jsonb),
(27, $j$["Vive em regiões secas e arenosas e cava tocas fundas para se abrigar.", "Quando assustado, se enrola numa bola para se proteger e rolar para longe.", "É pequeno, amarelado, com garras grossas e a pele dura e áspera.", "A pele é seca e escamosa; ele detesta água e se enrola como uma bolinha protegida."]$j$::jsonb),
(28, $j$["Vive em desertos e esconde-se em buracos durante o dia mais quente.", "Escala e cava muito bem e se defende enrolando-se de modo assustador.", "Tem o corpo amarelado, garras longas e barriga clara.", "As costas são cobertas de espinhos marrons e afiados, como um porco-espinho."]$j$::jsonb),
(29, $j$["É calmo, gentil e prefere evitar briga, vivendo em pastos e campos.", "Quando ameaçado, solta veneno pelos espinhos do corpo.", "Pequeno, azul-claro com manchas escuras, orelhas grandes e bigodes.", "Tem um espinho pequeno na testa e é a versão fêmea de uma espécie em que macho e fêmea são diferentes."]$j$::jsonb),
(30, $j$["É protetora com o grupo e prefere ficar quieta junto da família.", "Quando a família está em perigo, os espinhos se levantam e ela fica bem brava.", "Azul, com manchas escuras, orelhas grandes e dentes pontudos.", "Os espinhos encolhem quando está calma e crescem quando se zanga, protegendo os filhotes."]$j$::jsonb),
(31, $j$["Sempre defende os mais novos e enfrenta qualquer um para proteger o lar.", "Usa o corpo pesado para empurrar e derrubar inimigos.", "Grande, azul, com barriga creme e o corpo coberto de escamas duras.", "Tem uma armadura de escamas grossa, uma cauda pesada e é a forma mais forte da fêmea da espécie."]$j$::jsonb),
(32, $j$["É desconfiado e mantém as orelhas sempre em pé para ouvir perigo.", "Ataca com veneno quando acuado e é muito atento ao ambiente.", "Pequeno, roxo, com manchas escuras e orelhas grandes.", "Tem um chifre venenoso na testa e é o macho de uma espécie em que macho e fêmea são diferentes."]$j$::jsonb),
(33, $j$["Fica nervoso e agressivo quando alguém se aproxima e vive sempre em alerta.", "Ataca com o chifre afiado que solta veneno.", "Roxo, com espinhos nas costas e orelhas grandes.", "Tem um chifre muito maior que antes, duro como diamante, e é a forma do meio do macho da espécie."]$j$::jsonb),
(34, $j$["É bravo e forte, protegendo o território com muita força.", "Usa a cauda grossa para derrubar inimigos e tem um chifre perigoso.", "Grande, roxo, com escamas grossas e espinhos nas costas.", "Tem um chifre enorme e venenoso e uma cauda poderosa, a forma mais forte do macho da espécie."]$j$::jsonb),
(35, $j$["É raro, tímido e aparece mais à noite, sob a lua cheia.", "Dança em grupo à noite e foge quando alguém tenta vê-lo.", "Pequeno, rosa, com orelhas pontudas e um cachinho na testa.", "Tem asinhas pequenas nas costas e dizem que veio da Lua."]$j$::jsonb),
(36, $j$["Vive escondido em montanhas e raramente aparece para pessoas.", "Tem ouvido tão bom que escuta coisas a quilômetros de distância.", "Grande, rosa, com orelhas pontudas e asas pequenas.", "Pode pular tão leve que parece andar sobre a água e é ligado à Lua."]$j$::jsonb),
(37, $j$["Vive em grupos em lugares quentes e é brincalhão.", "Quando nasce, tem só uma cauda; com o tempo, ganha mais.", "Pequeno, marrom-avermelhado, com cachinhos na cabeça.", "Tem seis caudas encaracoladas, como uma raposinha."]$j$::jsonb),
(38, $j$["É elegante, inteligente e vive muitos e muitos anos.", "Se puxarem suas caudas, pode amaldiçoar a pessoa por anos.", "Raposa grande de pelo dourado e brilhante.", "Tem nove caudas longas e douradas que balançam com graça."]$j$::jsonb),
(39, $j$["Adora cantar e sempre quer que todos a escutem com atenção.", "Canta uma melodia que faz quem ouvir dormir na hora.", "Pequena, rosa, redonda, com olhos grandes.", "Quando se zanga com quem dormiu na cantoria, rabisca o rosto da pessoa; é uma bolinha que incha como balão."]$j$::jsonb),
(40, $j$["É fofo, calmo e adora ser abraçado por quem conhece.", "Quando ameaçado, incha o corpo para parecer maior e assustar o inimigo.", "Rosa e branco, com orelhas grandes e um corpo macio.", "Tem pelagem macia e elástica que incha como balão e é muito gostosa de abraçar."]$j$::jsonb),
(41, $j$["Vive em cavernas escuras e só sai à noite.", "Bebe o sangue de outros animais e usa o som para se guiar no escuro.", "Pequeno, azul, com asas roxas e orelhas grandes.", "Não tem olhos e voa em grupos fazendo ultrassom para enxergar."]$j$::jsonb),
(42, $j$["É ativo de noite e vive em cavernas profundas.", "Suga o sangue das presas até ficarem fracas.", "Azul, com asas grandes e roxas.", "Tem uma boca enorme cheia de dentes, que ocupa quase todo o corpo."]$j$::jsonb),
(43, $j$["Fica enterrado de dia e sai à noite para passear.", "Absorve nutrientes da terra e espalha sementes andando.", "Pequeno, azul, redondo e com olhos vermelhos.", "Parece um nabo ambulante com folhas verdes saindo da cabeça."]$j$::jsonb),
(44, $j$["Vive em lugares úmidos e é um pouco desajeitado.", "Solta um cheiro horrível que faz qualquer um fugir.", "Azul, com folhas murchas e baba saindo da boca.", "Tem uma grande flor laranja na cabeça que solta um mau cheiro terrível."]$j$::jsonb),
(45, $j$["Fica em matas densas e tropicais, perto de árvores grandes.", "Solta pó alérgico das pétalas que paralisa quem está perto.", "Azul, pequeno, com uma flor gigante na cabeça.", "Tem uma flor vermelha gigante com pintas brancas na cabeça, aberta como um guarda-chuva."]$j$::jsonb),
(46, $j$["Vive em florestas escuras e úmidas, perto de raízes de árvores.", "Tem cogumelos nas costas que sugam a energia dele.", "Pequeno, laranja, com várias patas e garras.", "Tem dois cogumelos vermelhos nas costas, que dizem ser os donos de verdade."]$j$::jsonb),
(47, $j$["Fica em lugares escuros e úmidos, sempre debaixo de árvores.", "O cogumelo nas costas controla seu corpo e espalha esporos.", "Laranja, com olhos brancos e garras grandes.", "Tem um cogumelo gigante vermelho com bolinhas que cobre o corpo inteiro."]$j$::jsonb),
(48, $j$["É ativo à noite e é atraído pela luz.", "Come pequenos insetos à noite e solta veneno pelos pelos quando alguém encosta nele.", "Pequeno, roxo e peludo, com antenas.", "Tem olhos grandes e vermelhos que enxergam até no escuro, e o corpo todo coberto de pelos."]$j$::jsonb),
(49, $j$["Voa à noite, atraído por luzes de casas e postes.", "Bate as asas soltando um pó venenoso que paralisa.", "Mariposa roxa com asas grandes e olhos verdes.", "As asas soltam um pó roxo que muda de cor conforme o efeito."]$j$::jsonb),
(50, $j$["Vive debaixo da terra e quase nunca é visto por inteiro.", "Cava túneis que deixam a terra fofa e boa para plantar.", "É bem pequeno, marrom, com nariz rosado.", "Só a cabeça aparece fora do buraco, e ninguém sabe como é o corpo embaixo da terra."]$j$::jsonb),
(51, $j$["Vive debaixo da terra e quase nunca aparece por inteiro na superfície.", "Trabalha em grupo para cavar túneis enormes, e o solo por onde passa fica fofo e bom para plantar.", "Corpo marrom e liso, com narizes grandes e rosados, sempre saindo de um buraco no chão.", "São três cabeças grudadas lado a lado, que sobem e descem do buraco num ritmo próprio."]$j$::jsonb),
(52, $j$["Anda pelas cidades de noite e adora ficar perto de onde as pessoas moram.", "É ladrão de coisas brilhantes: leva para o esconderijo tudo o que reluz, principalmente dinheiro.", "Felino pequeno e bege, que costuma andar sobre duas patas, com bigodes compridos.", "Tem uma moeda dourada brilhando bem no meio da testa."]$j$::jsonb),
(53, $j$["Orgulhoso e de humor difícil, não aceita ordens de qualquer um.", "Caça em silêncio e ataca de surpresa; quem cria um em casa vira símbolo de luxo.", "Felino elegante de pelo creme, corpo esguio e andar sobre quatro patas.", "Carrega uma pedra vermelha preciosa encravada no centro da testa."]$j$::jsonb),
(54, $j$["Passa o dia parado à beira de lagos, com cara de quem não entende nada.", "Vive com dor de cabeça; quando ela aperta demais, solta poderes da mente sem perceber.", "Ave aquática amarela e gordinha, que anda sobre duas patas de pés espalmados.", "Segura a cabeça com as duas mãos o tempo todo, com expressão confusa."]$j$::jsonb),
(55, $j$["Nadador campeão, vence correntezas fortes sem esforço nenhum.", "Na água é rápido e caçador; às vezes usa poderes da mente quando está concentrado.", "Corpo azul e esguio, com mãos e pés palmados ótimos para nadar.", "Tem uma pedra vermelha na testa que brilha quando ele usa seus poderes."]$j$::jsonb),
(56, $j$["Vive nas árvores das montanhas e anda em bandos barulhentos.", "Fica furioso por qualquer coisa e parte para cima sem pensar; acalmá-lo é quase impossível.", "Bolinha peluda bege, com rabo fino, braços curtos e focinho de porco.", "Macaco que se irrita do nada e sai distribuindo socos e chutes."]$j$::jsonb),
(57, $j$["Quem cruza o caminho dele se arrepende: nunca esquece uma provocação.", "Persegue o inimigo por horas a fio e não para até descontar toda a raiva.", "Corpo redondo e peludo, mais alto que a forma anterior, usando braceletes de metal nos pulsos.", "É a raiva em pessoa: quanto mais bravo fica, mais forte bate."]$j$::jsonb),
(58, $j$["Fiel e corajoso, protege seu território e seu dono com unhas e dentes.", "Late alto para afastar estranhos e é muito usado como cão de guarda pela polícia.", "Filhote de pelo laranja com listras pretas e uma juba creme no peito e na cabeça.", "Cachorrinho que cospe fogo e tem um faro capaz de nunca esquecer um cheiro."]$j$::jsonb),
(59, $j$["Lendas antigas falam dele como uma criatura nobre e admirada por muitos povos.", "Corre distâncias enormes em um único dia, mais rápido do que qualquer cavalo.", "Cão enorme, de pelo laranja com listras pretas e juba farta cor de creme.", "Grande cachorro de fogo, chamado de lendário pela beleza e pela velocidade."]$j$::jsonb),
(60, $j$["Vive em lagos e lagoas e anda meio desajeitado quando sai da água.", "Ainda não firma bem as pernas em terra; prefere nadar e se esconder no fundo.", "Pequeno, redondo e azul, com pele fina e um rabo de girino.", "Na barriga branca tem um espiral, que mostra os órgãos através da pele."]$j$::jsonb),
(61, $j$["Consegue viver tanto dentro quanto fora da água sem problemas.", "Transpira sem parar para manter a pele úmida; o suor deixa o corpo escorregadio.", "Corpo azul e redondo, agora com braços e pernas fortes, sem rabo.", "Tem um espiral na barriga que deixa quem olha muito tonto."]$j$::jsonb),
(62, $j$["Nadador incansável, atravessa oceanos inteiros sem descansar.", "Usa braços musculosos para lutar; conhece golpes de luta além dos de água.", "Corpo azul e robusto, com luvas brancas nas mãos e cara de poucos amigos.", "Lutador de água com um espiral na barriga e músculos de sobra."]$j$::jsonb),
(63, $j$["Dorme quase o dia inteiro e mal sai do lugar.", "Sente o perigo antes de acontecer e some num piscar de olhos, sem lutar.", "Corpo amarelo com placas marrons, cauda grossa e olhos sempre fechados.", "Foge de tudo se teletransportando, mesmo enquanto está dormindo."]$j$::jsonb),
(64, $j$["Por perto dele aparelhos eletrônicos costumam falhar sem motivo.", "Emite ondas da mente que causam dor de cabeça em quem fica perto.", "Corpo amarelo, bigode comprido e uma estrela vermelha na testa.", "Segura uma colher de prata, que ele dobra só com a força da mente."]$j$::jsonb),
(65, $j$["Dizem que sua inteligência passa da de um supercomputador.", "Lembra de tudo o que viveu desde que nasceu, sem esquecer nenhum detalhe.", "Corpo magro e amarelo, cabeça grande e bigode longo pendurado.", "Carrega uma colher em cada mão e tem um cérebro que nunca para de crescer."]$j$::jsonb),
(66, $j$["Adora treinar e passa o dia inteiro se exercitando.", "Levanta pesos muito maiores que ele e gosta de ajudar em trabalho pesado.", "Pequeno, cinza-azulado, com três cristas na cabeça e corpo cheio de músculos.", "Lutador mirim que treina com pedras gigantes para ficar ainda mais forte."]$j$::jsonb),
(67, $j$["Muito procurado para mudanças e obras por causa da força.", "Nunca se cansa; consegue carregar cargas pesadas o dia todo sem reclamar.", "Corpo cinza musculoso, com uma faixa de cinto e cristas na cabeça.", "Usa um cinto de campeão para segurar a força enorme dos músculos."]$j$::jsonb),
(68, $j$["Lutador que conhece todos os estilos de combate existentes.", "Consegue dar centenas de golpes em pouquíssimo tempo, deixando o rival sem reação.", "Corpo cinza enorme, de cueca preta com cinto dourado e lábios grossos.", "Tem quatro braços musculosos e consegue socar em todas as direções."]$j$::jsonb),
(69, $j$["Gosta de lugares quentes e úmidos e fica parado esperando a presa.", "Captura pequenos insetos de surpresa com um movimento rápido do corpo.", "Corpo fininho como um caule, verde, com folhas que parecem braços.", "Tem cabeça de sino amarela e raízes no lugar dos pés."]$j$::jsonb),
(70, $j$["Vive pendurado nos galhos das florestas, quieto e paciente.", "Engole o que passa por perto e derrete com um ácido que guarda dentro.", "Planta amarela e verde, com duas folhas grandes nas laterais do corpo.", "Parece um sino com boca, que fica pendurado esperando presas caírem dentro."]$j$::jsonb),
(71, $j$["Vive no meio da selva fechada e quase ninguém volta para contar.", "Atrai presas com um cheiro doce e depois as dissolve lentamente por dentro.", "Planta enorme e amarela, com uma longa vinha marrom saindo do alto.", "Planta carnívora gigante em forma de jarro, com uma boca larga e escancarada."]$j$::jsonb),
(72, $j$["Vive no mar e às vezes aparece em grupos perto das praias.", "Seus tentáculos soltam veneno, e banhistas desatentos levam ferroadas.", "Corpo transparente e azulado, com dois tentáculos longos embaixo.", "Água-viva com duas pedras vermelhas no topo do corpo."]$j$::jsonb),
(73, $j$["Fica escondido no fundo do mar e é um terror para navegantes.", "Prende a presa com dezenas de tentáculos e a deixa fraca com veneno.", "Corpo azul e grande, com várias pedras vermelhas pelo topo.", "Água-viva enorme com oitenta tentáculos, que crescem e encolhem como quiser."]$j$::jsonb),
(74, $j$["Vive em trilhas de montanha e quase não é notado por quem passa.", "Às vezes, quem caminha pisa nele sem querer, achando que é parte do chão.", "Corpo redondo e cinza, sem pernas, com dois braços fortes.", "É uma pedra com braços, que fica parada no caminho das trilhas."]$j$::jsonb),
(75, $j$["Vive nas montanhas e se alimenta de pedras e musgo.", "Desce morros rolando, sem se importar com o que encontra pela frente.", "Corpo arredondado de pedra cinza, com quatro braços.", "Uma rocha grande que rola montanha abaixo, quebrando tudo no caminho."]$j$::jsonb),
(76, $j$["Pesado e tranquilo, fica a maior parte do tempo parado em encostas.", "Troca de casca uma vez por ano; a casca velha vira terra para plantas.", "Corpo coberto por um casco de pedra grosso, com cabeça e membros saindo dele.", "Uma bola de pedra gigante que explode quando se sente ameaçada."]$j$::jsonb),
(77, $j$["Ao nascer, mal consegue ficar de pé, mas aprende rápido a correr.", "Corre por campos abertos e se fortalece correndo atrás dos mais velhos.", "Quadrúpede de pelo creme, com cascos firmes e pernas longas.", "Um pônei com crina e cauda de fogo."]$j$::jsonb),
(78, $j$["Sempre corre a toda velocidade em busca de algo mais rápido que ele.", "Gosta de competir e só para de correr quando perde a disputa.", "Quadrúpede branco e elegante, com crina longa e cascos firmes.", "Cavalo com chifre na testa e chamas em vez de crina."]$j$::jsonb),
(79, $j$["Lento, demora muito para perceber o que acontece ao redor.", "Fica horas sentado à beira da água, pescando com uma parte do corpo.", "Corpo rosa e gordinho, cara de quem nunca tem pressa.", "Pesca com o rabo na água, mesmo depois de perder um pedaço dele."]$j$::jsonb),
(80, $j$["Continua lento e distraído, mesmo depois de evoluir.", "Algo mordeu uma parte do corpo dele e nunca mais soltou.", "Corpo rosa, anda sobre duas pernas e tem aparência sonolenta.", "Tem uma concha grudada na cauda, que fica mordendo-a para sempre."]$j$::jsonb),
(81, $j$["Às vezes aparece sem aviso perto de usinas de energia.", "Se alimenta de eletricidade e flutua sem usar asas.", "Bola de metal cinza, com um único olho grande no meio.", "Tem dois ímãs nas laterais e parafusos no corpo."]$j$::jsonb),
(82, $j$["Quando aparece, o ar em volta fica estranho e cheio de estática.", "Solta ondas que bagunçam aparelhos elétricos e deixam a região sem sinal.", "Três bolas cinzas de metal grudadas, cada uma com seu olho.", "São três ímãs unidos que flutuam juntos e soltam choques fortes."]$j$::jsonb),
(83, $j$["Raramente aparece em grupo; é difícil encontrar um.", "Usa um objeto para lutar, mas às vezes o come em caso de fome.", "Ave marrom com bico amarelo e expressão de valentão.", "Pato que sempre carrega um talo de alho-poró no bico ou na asa."]$j$::jsonb),
(84, $j$["Vive em campos abertos e quase não sabe voar.", "Corre muito rápido e deixa pegadas fundas por onde passa.", "Ave marrom, corpo arredondado e pernas longas e fortes.", "Ave com duas cabeças, que pensam e agem de forma diferente."]$j$::jsonb),
(85, $j$["Muito agitado, nunca para quieto e reage rápido a tudo.", "Corre a grandes velocidades em planícies, superando muitos animais.", "Ave marrom e grande, com pernas compridas e corpo forte.", "Tem três cabeças, cada uma com um humor diferente."]$j$::jsonb),
(86, $j$["Vive em lugares muito frios e adora nadar em águas geladas.", "Aguenta o frio do mar polar sem problema nenhum.", "Corpo branco e gordinho, com nadadeiras e cauda pequena.", "Foca com um chifre pequeno na testa."]$j$::jsonb),
(87, $j$["Dorme sobre blocos de gelo em mares frios e tranquilos.", "Nada com elegância em águas geladas e enfrenta qualquer frio.", "Corpo longo e branco, com rabo comprido e nadadeiras.", "Foca branca, com chifre e corpo todo coberto por pelo branco."]$j$::jsonb),
(88, $j$["Gosta de lugares sujos, como esgotos e lixões.", "Come lixo e restos, deixando um cheiro ruim por onde passa.", "Corpo mole e roxo, sem forma fixa, que escorre pelo chão.", "Uma lama roxa viva, que deixa veneno até nas pegadas."]$j$::jsonb),
(89, $j$["Vive em lugares muito poluídos e não sobrevive em lugares limpos.", "Seu cheiro é tão forte que deixa as pessoas tontas só de chegar perto.", "Corpo roxo, grande e mole, com braços que escorrem.", "Uma montanha de lama tóxica que mata plantas ao passar."]$j$::jsonb),
(90, $j$["Vive no fundo do mar, fechado a maior parte do tempo.", "Se defende fechando a casca dura, que quase nada consegue quebrar.", "Concha roxa com bordas pontudas e um corpo escuro dentro.", "Tem a língua para fora da concha o tempo todo."]$j$::jsonb),
(91, $j$["Fica no fundo do mar e quase não se move.", "Atira espinhos da concha para se defender de qualquer ameaça.", "Concha grande e escura, com muitas pontas e bordas.", "Tem uma pérola escura e um rosto sério dentro da concha cheia de espinhos."]$j$::jsonb),
(92, $j$["Aparece em lugares abandonados e escuros, sempre à noite.", "Envolve as vítimas com gás e as faz dormir.", "Corpo feito de gás roxo, sem forma fixa.", "Uma bola preta com sorriso enorme, cercada por gás roxo."]$j$::jsonb),
(93, $j$["Some em paredes e aparece de repente para assustar as pessoas.", "Lambe as vítimas e as faz tremer de frio.", "Corpo roxo e flutuante, com mãos soltas no ar.", "Fantasma com mãos que flutuam separadas do corpo."]$j$::jsonb),
(94, $j$["Se esconde nas sombras e espera para pregar peças.", "Gosta de assustar e roubar o calor de quem está perto.", "Corpo roxo e redondo, com espinhos nas costas.", "Tem um sorriso grande e malicioso e olhos vermelhos."]$j$::jsonb),
(95, $j$["Vive debaixo da terra e cava túneis enormes.", "Abre caminho comendo pedras e deixando buracos por onde passa.", "Corpo comprido e cinza, feito de pedras redondas ligadas.", "Uma serpente gigante de pedras, com chifre na cabeça."]$j$::jsonb),
(96, $j$["Aparece de noite, perto de quem está dormindo.", "Come sonhos das pessoas, preferindo os mais felizes.", "Corpo amarelo e marrom, com nariz comprido.", "Tem tromba e se alimenta dos sonhos dos outros."]$j$::jsonb),
(97, $j$["Fica parado observando as pessoas, sempre em silêncio.", "Hipnotiza as vítimas e as faz dormir para roubar os sonhos.", "Corpo amarelo com gola branca e peluda.", "Segura um pêndulo que balança para hipnotizar."]$j$::jsonb),
(98, $j$["Vive na areia da praia, perto da água.", "Belisca com as pinças tudo o que se aproxima demais.", "Corpo laranja e branco, com pernas finas.", "Caranguejo com pinças grandes que podem quebrar coisas."]$j$::jsonb),
(99, $j$["Vive perto do mar e anda de lado.", "Sua garra é tão forte que pode esmagar quase tudo.", "Corpo laranja e grande, com casca dura.", "Caranguejo com uma pinça muito maior que a outra."]$j$::jsonb),
(100, $j$["Costuma aparecer em lugares com muita energia elétrica.", "Explode quando é tocado, assustando quem chega perto.", "Corpo redondo, metade vermelho e metade branco.", "Parece uma bola de captura, mas explode de repente."]$j$::jsonb),
(101, $j$["Costuma ficar parado em lugares cheios de máquinas e cabos, e quase nunca fica calmo por muito tempo.", "Rola em alta velocidade e explode quando se irrita ou leva um susto, sem se importar com quem está perto.", "Corpo totalmente redondo e liso, sem braços nem pernas, com olhos bravos no meio.", "Parece uma Poké Bola gigante de cabeça para baixo: vermelho embaixo, branco em cima."]$j$::jsonb),
(102, $j$["Vive sempre em grupo e se comunica com os companheiros por algo parecido com telepatia.", "Quando um se perde do bando, os outros se juntam rapidamente para buscá-lo e se defender juntos.", "Pequenos, rosados e ovais, cada um com um rosto diferente e rachaduras na casca.", "É um punhado de seis ovos com caras, que parecem sementes caídas de uma árvore."]$j$::jsonb),
(103, $j$["Prefere lugares quentes e ensolarados, e anda devagar e pensativo pelo meio da mata tropical.", "Suas várias cabeças às vezes discordam entre si, e ele se defende com poderes da mente.", "Alto, com tronco grosso marrom e pés curtos, lembra uma planta que caminha sobre duas pernas.", "Uma palmeira ambulante com três cabeças em forma de coco entre as folhas no topo."]$j$::jsonb),
(104, $j$["Solitário e tímido, raramente se aproxima de outros e costuma chorar sozinho nas noites de lua cheia.", "Carrega sempre um osso, que usa como porrete para bater em quem chega perto demais.", "Pequeno, marrom, de barriga clara e cauda curta, caminhando sobre as duas patas traseiras.", "Usa na cabeça o crânio da própria mãe, como se fosse um capacete."]$j$::jsonb),
(105, $j$["Antes era medroso, mas hoje é um guerreiro feroz e corajoso que não foge de briga.", "Luta com muita habilidade usando um osso como bumerangue, que arremessa e pega de volta.", "Corpo marrom e firme, um pouco maior que a forma anterior, com o crânio já preso à cabeça.", "Gira um osso grosso como arma de arremesso e usa uma caveira como capacete."]$j$::jsonb),
(106, $j$["Disciplinado e incansável, treina todos os dias para melhorar seus golpes e vencer qualquer adversário.", "Luta à distância, atacando de surpresa e mantendo o oponente longe com velocidade impressionante.", "Corpo marrom sem cabeça aparente, com olhos no tronco e nenhuma boca visível.", "Suas pernas esticam como molas e acertam chutes poderosos de muito longe."]$j$::jsonb),
(107, $j$["Tem espírito de atleta competitivo e nunca desiste, mesmo quando está cansado ou ferido.", "Ataca com sequências de golpes tão rápidos que o adversário mal consegue enxergar.", "Corpo marrom, olhos firmes, uma espécie de saia roxa na cintura e postura de lutador.", "Usa luvas vermelhas de boxe e luta como um campeão de ringue."]$j$::jsonb),
(108, $j$["Curioso, examina tudo o que encontra pelo caminho, sem pressa e de forma meio desajeitada.", "Captura comida e se defende usando uma parte do corpo que deixa o inimigo arrepiado e paralisado.", "Corpo rosado e roliço, barriga com listras amarelas e cauda grossa.", "Tem uma língua enorme, muito maior que o próprio corpo, que adora lamber tudo."]$j$::jsonb),
(109, $j$["Gosta de lugares sujos, fábricas abandonadas e lixões, onde o ar é pesado e poluído.", "Se defende soltando um ar fedido e tóxico que deixa todo mundo tonto.", "Corpo roxo e redondo, flutuando no ar, coberto de bolinhas e com cara de mau.", "Uma bola de gás venenoso cheia de crateras e uma caveira desenhada na barriga."]$j$::jsonb),
(110, $j$["Vive perto de lugares poluídos e se sente em casa onde ninguém mais aguenta ficar.", "Quanto mais sujeira e lixo encontra, mais forte fica o veneno que espalha ao redor.", "Roxo, com crateras pela pele e fumaça vazando o tempo todo, flutuando devagar.", "São duas bolas de gás grudadas, uma grande e outra pequena, cada uma com sua cara."]$j$::jsonb),
(111, $j$["Teimoso e esquecido, corre em linha reta e muitas vezes esquece por que começou a correr.", "Derruba árvores e pedras no caminho com a força do corpo, sem desviar de nada.", "Quatro patas, pele cinza muito grossa e cheia de placas, parece um tanque vivo.", "Tem um chifre na ponta do focinho e investe de cabeça como um rinoceronte de pedra."]$j$::jsonb),
(112, $j$["Muito resistente, aguenta calor intenso e impactos fortes sem nem parecer sentir dor.", "Seu couro protege de lava e pancadas, e consegue esmagar rochas com facilidade.", "Ficou de pé sobre as patas de trás, enorme, com pele cinzenta e rabo grosso.", "Tem um chifre que gira como broca e perfura até pedra dura."]$j$::jsonb),
(113, $j$["Gentil e generosa, adora cuidar de quem está machucado e ajuda em hospitais.", "Dizem que traz sorte, e quem a encontra na natureza costuma ganhar um presente.", "Corpo rosado e redondo, com uma bolsinha na barriga e pequenas pontas na cabeça.", "Carrega na bolsa um ovo nutritivo que oferece a quem precisa."]$j$::jsonb),
(114, $j$["Calmo e misterioso, vive escondido em matas fechadas e não gosta de chamar atenção.", "Prende os inimigos enrolando-os, e o que perde volta a crescer rapidamente.", "Seu corpo de verdade nunca foi visto; só aparecem dois olhos e pés vermelhos.", "É uma bola de cipós azuis emaranhados que não para de crescer."]$j$::jsonb),
(115, $j$["Muito protetora, vive em planícies abertas e defende sua família com unhas e dentes.", "Raramente perde a calma, mas fica furiosa se alguém ameaça seu filhote.", "Grande, marrom, com focinho comprido e forte, andando sobre duas pernas grossas.", "Carrega um filhote dentro de uma bolsa na barriga, como um canguru."]$j$::jsonb),
(116, $j$["Vive em recifes e águas calmas, e se esconde rapidinho quando sente algum perigo.", "Atira jatos de tinta para fugir ou para acertar insetos sobre a água.", "Pequeno e azul, com barriga amarela clara e nadadeira nas costas.", "Parece um cavalo-marinho de focinho fino que nada com o rabo enrolado."]$j$::jsonb),
(117, $j$["Mais agressivo que antes, defende seu território com bastante determinação no fundo do mar.", "Seus espinhos causam desmaios em quem toca, e ele nada girando para criar redemoinhos.", "Azul, maior que a forma anterior, com nadadeiras pontiagudas em volta do corpo.", "Um cavalo-marinho cheio de barbatanas afiadas como espinhos nas laterais."]$j$::jsonb),
(118, $j$["Gosta de rios e lagos limpos, e é admirada pela elegância com que nada.", "Apesar da aparência delicada, defende-se com bastante força e pode ser difícil de pegar.", "Corpo branco com manchas laranjas e nadadeiras longas e soltas, como véus.", "Peixinho dourado com um chifre pontudo na testa."]$j$::jsonb),
(119, $j$["No outono, sobe correntezas fortes de rio para colocar seus ovos.", "Usa a força de nadar contra a água e cava ninhos no fundo das pedras.", "Peixe grande e branco com manchas laranja, com lábios grossos e nadadeiras espalhadas.", "Peixe-rei com um chifre pontiagudo usado para furar pedras."]$j$::jsonb),
(120, $j$["Aparece em praias à noite e às vezes brilha junto com o céu estrelado.", "Mesmo partido, consegue recuperar o corpo inteiro rapidamente, desde que o centro esteja intacto.", "Corpo marrom duro, com cinco pontas iguais e um núcleo brilhante no meio.", "Uma estrela-do-mar com uma joia vermelha no centro."]$j$::jsonb),
(121, $j$["Muito misterioso, alguns acreditam que vem do espaço por causa de seus sinais estranhos.", "Gira o corpo enquanto nada e se comunica com o céu à noite por meio de luzes.", "Corpo roxo com várias pontas, como duas estrelas sobrepostas.", "Sua joia central brilha em várias cores, como se fosse um cristal mágico."]$j$::jsonb),
(122, $j$["Brincalhão e muito talentoso, adora se apresentar como se estivesse em um palco.", "Cria muros e barreiras que não se veem, só para atrapalhar quem se aproxima.", "Corpo parecido com o de um humano, com bochechas vermelhas e mãos grandes.", "É um mímico que finge estar preso numa caixa invisível."]$j$::jsonb),
(123, $j$["Ágil e veloz, ataca em bandos nos campos de grama alta.", "Avança tão rápido que parece sumir, cortando tudo pelo caminho.", "Corpo verde, com asas finas nas costas e cara de inseto bravo.", "Seus braços são duas lâminas afiadas como foices."]$j$::jsonb),
(124, $j$["Adora dançar e se balançar no ritmo, e parece estar sempre se expressando.", "Usa beijos e movimentos de quadril para confundir ou adormecer os inimigos.", "Corpo roxo, com longos cabelos dourados e lábios vermelhos grandes.", "Uma figura humana que domina o gelo e o charme com suas danças."]$j$::jsonb),
(125, $j$["Fica agitado durante tempestades e procura lugares com muita energia elétrica.", "Libera choques fortes e gira os braços para gerar mais carga.", "Corpo amarelo com listras pretas, como um tigre, e pequenas antenas.", "Um lutador que solta raios e adora quedas de energia."]$j$::jsonb),
(126, $j$["Vive perto de vulcões ou regiões muito quentes, onde a temperatura é extrema.", "Solta chamas da boca e do corpo quando está em perigo.", "Corpo laranja com manchas amarelas, como um fogo vivo.", "Um bicho com cabeça de pato e corpo de lagarta flamejante."]$j$::jsonb),
(127, $j$["Gosta de lugares quentes e espera paciente até que um alvo apareça.", "Agarra os inimigos e os esmaga com força, sem soltar.", "Corpo marrom e grosso, com patas curtas e olhos ferozes.", "Possui duas pinças enormes saindo da cabeça, como chifres."]$j$::jsonb),
(128, $j$["Vive em bandos e corre pelas planícies, sempre em busca de briga.", "Bate a cauda contra o próprio corpo para se animar antes de atacar.", "Corpo marrom com crina escura e chifres curvos para os lados.", "Um touro selvagem com três caudas chicoteando no ar."]$j$::jsonb),
(129, $j$["Nada sem rumo pelos rios, fácil de encontrar e de pegar.", "Considerado um dos mais fracos, só sabe pular e se debater fora d'água.", "Peixe vermelho e escamoso, com bigodes e nadadeiras amarelas.", "Pula sem parar e não serve para nada... ou quase nada."]$j$::jsonb),
(130, $j$["Destruidor e temido, aparece quando o mar está agitado e furioso.", "Cria tempestades e ataca tudo ao seu redor, cheio de raiva.", "Serpente marinha gigante, azul com barriga amarela, e boca enorme.", "Um dragão do mar que nasce de um peixe fraco e sem força."]$j$::jsonb),
(131, $j$["Muito inteligente e gentil, entende o que as pessoas dizem e adora cantar.", "Gosta de carregar pessoas pelo mar e acalmar as águas com sua presença.", "Corpo azul com uma concha cinza nas costas e chifre na cabeça.", "Um transporte marinho em forma de dinossauro de pescoço longo."]$j$::jsonb),
(132, $j$["Raramente ataca, mas pode imitar qualquer coisa com grande perfeição.", "Copia a aparência e os golpes de quem estiver em sua frente.", "Uma massa roxa e mole, sem forma definida, com olhos e boca simples.", "Pode virar qualquer Pokémon, mas mantém a mesma carinha."]$j$::jsonb),
(133, $j$["Curioso, adapta-se facilmente a ambientes diferentes, sempre explorando.", "Pode mudar completamente dependendo de pedras ou do lugar onde vive.", "Pelagem marrom macia, cauda fofa e colar branco no pescoço.", "Pode evoluir de várias formas diferentes, cada uma com um elemento."]$j$::jsonb),
(134, $j$["Vive perto de lagos e rios, sempre deslizando pela água.", "Pode se dissolver na água e se tornar quase invisível.", "Corpo azul com uma barbatana no rabo e uma gola branca.", "Uma das formas evoluídas que domina a água e parece uma sereia."]$j$::jsonb),
(135, $j$["Agitado e elétrico, seu humor muda o tempo todo.", "Seus pelos ficam arrepiados e soltam choques quando fica bravo.", "Corpo amarelo e pontudo, com uma gola branca em volta do pescoço.", "Uma das formas evoluídas que lança agulhas elétricas pelo corpo."]$j$::jsonb),
(136, $j$["Gosta de lugares quentes e não suporta o frio.", "Armazena calor no corpo e solta labaredas para atacar.", "Corpo vermelho e peludo, com uma gola amarela e cauda fofa.", "Uma das formas evoluídas que domina o fogo e é toda felpuda."]$j$::jsonb),
(137, $j$["Vive em computadores e pode viajar pela internet.", "Foi criado pelo homem e é feito de dados e códigos.", "Corpo formado por blocos coloridos, com aparência de brinquedo digital.", "O primeiro Pokémon artificial, com formas geométricas e cores vivas."]$j$::jsonb),
(138, $j$["Era muito comum no passado, mas hoje só vive em fósseis.", "Usa os tentáculos para se mover e caçar presas no fundo do mar.", "Corpo azul com uma concha enrolada em espiral.", "Um molusco pré-histórico que voltou à vida de um fóssil."]$j$::jsonb),
(139, $j$["Muito antigo, vivia nos oceanos milhões de anos atrás.", "Seus tentáculos fortes prendem presas, e a concha o protege.", "Corpo azul com concha grande e pontiaguda nas costas.", "Um molusco com bico e tentáculos, ressuscitado de fóssil."]$j$::jsonb),
(140, $j$["Vivia na praia e era comum há muito tempo, mas desapareceu.", "Escondia-se na areia e só saía para pegar comida.", "Corpo pequeno, marrom, com olhos brilhantes na parte de baixo.", "Um crustáceo antigo recuperado de um fóssil."]$j$::jsonb),
(141, $j$["Caçador antigo que vivia nas águas e atacava com precisão.", "Usa suas garras afiadas para cortar presas e sugar seus fluidos.", "Corpo marrom com cabeça achatada e braços em forma de foice.", "Um predador do passado que voltou à vida de um fóssil."]$j$::jsonb),
(142, $j$["Voava pelos céus em tempos antigos, caçando sem piedade.", "Ataca com mordidas e garras, voando em alta velocidade.", "Corpo cinza, asas grandes e dentes afiados.", "Um réptil voador pré-histórico recuperado de âmbar."]$j$::jsonb),
(143, $j$["Passa a maior parte do tempo dormindo e não liga para nada.", "Come muito e só acorda para buscar mais comida.", "Corpo enorme e redondo, azul escuro com barriga clara.", "Bloqueia caminhos dormindo e só acorda com uma flauta."]$j$::jsonb),
(144, $j$["Ave lendária que raramente aparece e vive em montanhas geladas.", "Dizem que surge para ajudar viajantes perdidos na neve.", "Corpo azul com longas penas e cauda comprida.", "Ave lendária que controla o gelo e solta ventos congelantes."]$j$::jsonb),
(145, $j$["Ave lendária que aparece durante tempestades e tem penas brilhantes.", "Dizem que surge quando há raios e trovões fortes.", "Corpo amarelo com penas pontudas e asas grandes.", "Ave lendária que controla a eletricidade e voa entre as nuvens carregadas."]$j$::jsonb),
(146, $j$["Ave lendária que raramente aparece e tem um brilho intenso.", "Dizem que surge para trazer a primavera e o calor.", "Corpo amarelo com penas flamejantes e cauda longa.", "Ave lendária que controla o fogo e voa envolta em chamas."]$j$::jsonb),
(147, $j$["Muito raro, vive escondido em lagos profundos.", "Troca de pele várias vezes enquanto cresce.", "Corpo azul longo e fino, como uma serpente.", "Um pequeno dragão aquático com aletas brancas na cabeça."]$j$::jsonb),
(148, $j$["Raramente visto, dizem que pode mudar o clima.", "Brilha suavemente e voa sem asas.", "Corpo longo e azul, com joias no pescoço e na cauda.", "Um dragão elegante que controla o tempo."]$j$::jsonb),
(149, $j$["Muito inteligente e gentil, pode voar ao redor do mundo rapidamente.", "Ajuda pessoas em perigo no mar e salva náufragos.", "Corpo laranja e grande, com asas pequenas e antenas.", "Um dragão gentil e poderoso que voa muito rápido."]$j$::jsonb),
(150, $j$["Criado em laboratório, tem uma mente fria e calculista.", "Domina poderes psíquicos e não gosta de seres humanos.", "Corpo roxo e alto, com cauda grossa e olhos penetrantes.", "Um clone artificial muito poderoso, feito a partir de outro ser lendário."]$j$::jsonb),
(151, $j$["Extremamente raro, quase ninguém já viu.", "Dizem que possui o DNA de todos os outros.", "Corpo pequeno e rosado, com cauda longa e fina.", "Um ser lendário capaz de aprender qualquer golpe."]$j$::jsonb),
(152, $j$["Gosta de passar a tarde deitado em campos abertos, aproveitando cada raio de sol.", "É dócil e carinhoso com quem cuida dele, e costuma ser um dos primeiros companheiros de um treinador iniciante.", "Pequeno, de corpo verde-claro e quatro patas curtas, com olhos vermelhos e um colar de brotinhos no pescoço.", "Balança a grande folha da cabeça para medir o ar e espalhar um cheirinho suave."]$j$::jsonb),
(153, $j$["É protetor e não sai do lado de quem confia nele, mesmo nos momentos difíceis.", "O perfume que solta pode animar os amigos ou deixar os rivais nervosos.", "Tem corpo amarelo-claro, pescoço comprido e uma folha enrolada no topo da cabeça.", "Ao redor do pescoço carrega uma fileira de brotos verdes que lembram folhas de especiaria."]$j$::jsonb),
(154, $j$["Por onde passeia, a vegetação ao redor parece ganhar força e cor.", "Prefere acalmar uma briga a vencê-la, e seu cheiro deixa qualquer um sereno.", "É um bicho grande de quatro patas, verde-claro, com duas antenas na cabeça e pescoço longo.", "Uma flor enorme de pétalas rosadas se abre em volta do pescoço como uma gola."]$j$::jsonb),
(155, $j$["É acanhado e costuma se esconder quando aparece alguém estranho.", "Se defende acendendo calor de repente, para espantar quem se aproxima demais.", "Pequeno e de quatro patas, tem costas azul-escuras, barriga creme e olhos quase sempre fechados.", "Quando se assusta, labaredas brotam das costas, como uma fileira de chamas acesas."]$j$::jsonb),
(156, $j$["É ágil e escapa de ataques com saltos rápidos e esquivas.", "Usa o calor do próprio corpo para afastar inimigos e deixar o ar tremendo em volta.", "Corpo comprido e esguio, azul-escuro em cima e creme embaixo, lembrando um furão.", "Tem chamas acesas na cabeça e no traseiro, que crescem quando ele se irrita."]$j$::jsonb),
(157, $j$["Raramente se mostra nervoso, mas quando perde a paciência ninguém fica por perto.", "Esfrega os pelos para provocar explosões e se esconde atrás de ondas de calor.", "Grande e de pé sobre duas patas, tem corpo azul-escuro em cima e creme na barriga.", "Uma juba de fogo explode ao redor do pescoço quando ele parte para a briga."]$j$::jsonb),
(158, $j$["É travesso e brincalhão, cheio de energia desde que sai do ovo.", "Morde tudo o que encontra pela frente, inclusive o treinador, só por diversão.", "Pequeno, azul, anda em duas patas e tem uma crista vermelha nas costas.", "Tem uma bocarra cheia de dentes afiados, desproporcional ao tamanho do corpo."]$j$::jsonb),
(159, $j$["Nunca solta o que agarra com a boca, por mais que se debatam.", "Os dentes caem com frequência, mas sempre nascem novos no lugar.", "Corpo azul com uma faixa amarela em formato de V no peito e crista vermelha maior.", "Fica com a boca escancarada e balança o corpo de um lado para o outro antes de morder."]$j$::jsonb),
(160, $j$["Parece lento em terra, mas dentro d'água surpreende pela velocidade.", "Agarra a presa com uma mordida e só solta quando ela para de lutar.", "Enorme e pesado, de pele azul, barriga amarela e espinhos vermelhos ao longo das costas.", "Abre uma mandíbula gigantesca, capaz de assustar qualquer um, como um grande crocodilo de pé."]$j$::jsonb),
(161, $j$["Vive em bandos e sempre tem alguém de olho no perigo enquanto os outros dormem.", "Quando percebe ameaça, dá um guincho alto para alertar todo o grupo.", "Pequeno mamífero marrom com barriga creme, olhos grandes e orelhas pequenas.", "Fica de pé apoiado na ponta da cauda listrada para enxergar mais longe."]$j$::jsonb),
(162, $j$["Cava tocas com muitas saídas e se esconde nelas ao menor sinal de perigo.", "Escapa de quem tenta pegá-lo deslizando por buracos apertados com muita facilidade.", "Marrom com listras creme, tem patas curtíssimas e um rabo listrado e fofo.", "Seu corpo é tão comprido que forma uma espécie de tubo peludo, quase sem fim."]$j$::jsonb),
(163, $j$["Só sai do ninho depois que escurece e passa a noite toda acordado.", "Tem um senso de tempo impressionante e repete o mesmo ritual sempre na mesma hora.", "Ave pequena e redonda, marrom, com olhos vermelhos e manchas que lembram sobrancelhas.", "Fica equilibrado numa perna só, alternando o pé com um ritmo perfeito, como um relógio."]$j$::jsonb),
(164, $j$["É sábio e calmo, raramente toma uma atitude sem pensar antes.", "Caça no escuro em silêncio total, sem que a presa perceba sua chegada.", "Grande ave marrom com sobrancelhas longas e um padrão de olhos vermelhos marcantes.", "Enxerga perfeitamente sem luz nenhuma e consegue girar a cabeça quase totalmente para trás."]$j$::jsonb),
(165, $j$["É medroso quando está sozinho, mas ganha coragem no meio do grupo.", "No frio, junta-se aos companheiros em montinhos para se aquecer.", "Um inseto de corpo arredondado vermelho, com antenas e pequenas patas.", "Tem as costas vermelhas com cinco pintinhas pretas, como uma joaninha."]$j$::jsonb),
(166, $j$["Voa durante a noite e parece ficar mais disposto quando o céu está limpo.", "Luta usando socos rápidos com suas várias patinhas.", "Inseto vermelho, de pé, com antenas e asinhas, maior que a forma anterior.", "As pintas das costas aumentam e diminuem conforme o brilho das estrelas no céu."]$j$::jsonb),
(167, $j$["É paciente e passa horas parado esperando que algo apareça.", "Tece armadilhas de fios finíssimos e sente pelas vibrações quando algo ficou preso.", "Pequena aranha verde com listras pretas e um chifre branco na testa.", "Nas costas tem um desenho que parece um rosto sorrindo."]$j$::jsonb),
(168, $j$["Caça à noite e costuma prender fios nas presas para segui-las até o esconderijo.", "Solta fios muito resistentes tanto pela boca quanto pela ponta do corpo.", "Aranha vermelha com seis patas listradas de amarelo e roxo e um chifre na testa.", "Tem um ferrão também na traseira, parecendo ter duas cabeças em lados opostos."]$j$::jsonb),
(169, $j$["Dorme de dia em cavernas escuras e sai voando só depois do pôr do sol.", "Seu voo é tão silencioso que a presa nem percebe quando ele se aproxima.", "Morcego roxo de olhos amarelos, boca com presas e pés pequenos que servem de asa.", "Tem quatro asas, duas em cima e duas embaixo, que o tornam muito veloz."]$j$::jsonb),
(170, $j$["Vive nas profundezas escuras do mar, onde a luz do sol quase não chega.", "Solta choques fortes para espantar quem tenta caçá-lo.", "Peixinho azul de olhos vermelhos e grandes, com nadadeira em forma de cauda.", "Tem duas antenas com bolinhas luminosas, que piscam para conversar com outros."]$j$::jsonb),
(171, $j$["Vive bem no fundo do oceano e raramente sobe até a superfície.", "Atrai presas com a luz e as atordoa com descargas elétricas.", "Peixe grande e azul, com nadadeiras amarelas e barriga clara.", "Carrega duas esferas luminosas tão fortes que pode ser visto da superfície, como um farol."]$j$::jsonb),
(172, $j$["É curioso e se mete em tudo, sempre brincando com os amigos.", "Ainda não controla bem a própria energia e leva choque quando se assusta ou ri.", "Pequenino, amarelo, de bochechas rosadas e orelhas com pontas pretas.", "É o filhote de um famoso roedor elétrico, com uma orelha enorme e rabinho curto."]$j$::jsonb),
(173, $j$["Costuma ser visto em noites de céu limpo e cheio de estrelas.", "Tímido, dança em roda com outros iguais sob a luz da lua.", "Pequenino, rosa, quase em forma de estrela, com orelhinhas pontudas.", "Dizem que chega à Terra em noites de chuva de estrelas cadentes."]$j$::jsonb),
(174, $j$["Adora brincar e é muito fofo, por isso é querido pelas crianças.", "Seu jeito de se defender é cantar, embora ainda não acerte as notas.", "Rosa, pequenino e completamente redondo, com olhos grandes e um topete curto.", "Seu corpo é macio e elástico, e ele quica como uma bola quando anda."]$j$::jsonb),
(175, $j$["Dizem que traz alegria para quem o trata bem.", "Absorve as emoções boas das pessoas ao redor e as transforma em sorte.", "Bebê pequenino, de pele creme, pés pequenos e uma coroa com pontinhas na cabeça.", "Vive dentro de uma casca de ovo com triângulos vermelhos e azuis."]$j$::jsonb),
(176, $j$["Só aparece para pessoas de bom coração, e foge de quem é cruel.", "Espalha uma poeira brilhante que deixa todos mais alegres e esperançosos.", "Branco, com triângulos vermelhos e azuis na barriga e pés pequenos.", "Saiu da casca de ovo e ganhou asas para voar por aí espalhando felicidade."]$j$::jsonb),
(177, $j$["Passa horas parado, olhando para longe, sem que ninguém entenda o motivo.", "Pula de galho em galho, porque ainda não consegue voar direito.", "Ave pequenina e verde, com bico amarelo e penas vermelhas e amarelas na cabeça.", "Tem um olhar fixo e misterioso que, dizem, enxerga coisas que vão acontecer."]$j$::jsonb),
(178, $j$["Fica imóvel o dia inteiro, quase como uma estátua.", "Dizem que conhece os acontecimentos antes que eles cheguem e teme o que vê.", "Ave verde de pé, com asas que parecem um manto listrado de vermelho, branco e preto.", "Fica parada encarando o sol, com um olho no passado e outro no futuro."]$j$::jsonb),
(179, $j$["É calmo e convive bem com pessoas em fazendas.", "Sua lã é usada para fazer roupas, mas pode dar choque em quem toca.", "Ovelhinha azulada com um cachecol de lã branca e rabinho listrado.", "A lã fofa acumula eletricidade estática e fica arrepiada e brilhando."]$j$::jsonb),
(180, $j$["Fica mais irritado no tempo seco, quando dá choques com mais facilidade.", "Perdeu boa parte da lã, então a eletricidade escapa mais fácil.", "Rosado, anda em duas patas e tem um pouco de lã só na cabeça e nos quadris.", "Sua pele sem pelos é revestida por uma camada que o protege dos próprios choques."]$j$::jsonb),
(181, $j$["É gentil e leal, sempre pronto para ajudar quem estiver perdido.", "Usado como guia, dizem que salvava navegantes no escuro.", "Amarelo, de pé, com faixas pretas no pescoço e uma joia vermelha na testa.", "A ponta da cauda acende uma luz tão forte que já foi usada como farol."]$j$::jsonb),
(182, $j$["Adora dias de sol e costuma dançar quando o tempo esquenta.", "Diz-se que suas danças chamam a chuva depois de longos períodos secos.", "Pequenino, verde, com uma saia de folhas e corpinho arredondado.", "Tem flores vermelhas e amarelas na cabeça e balança as folhas como numa dança havaiana."]$j$::jsonb),
(183, $j$["Vive perto de rios e lagos e passa boa parte do dia brincando na água.", "A pelagem não deixa a água entrar, então ele nada sem problemas.", "Pequeno, azul e redondo, com orelhas arredondadas e barriga clara.", "O rabo termina numa bola que funciona como boia e o mantém na superfície."]$j$::jsonb),
(184, $j$["Passa horas no fundo dos rios sem precisar subir.", "Ouve tudo o que acontece debaixo d'água, até movimentos de longe.", "Corpo azul e branco, rechonchudo, com orelhas compridas de coelho.", "Faz bolhas de ar que guarda junto ao corpo para respirar no fundo."]$j$::jsonb),
(185, $j$["Fica quieto o dia inteiro para não chamar a atenção de ninguém.", "Odeia água: corre para longe assim que sente chuva chegando.", "Corpo marrom e cheio de nós, com braços verdes e olhos pequenos.", "Finge ser uma árvore, mas na verdade é feito de pedra."]$j$::jsonb),
(186, $j$["Gosta de ficar à beira dos lagos e lidera os companheiros.", "Quando ele grita, todos os outros parecidos vêm correndo para obedecer.", "Verde, em pé, rechonchudo, com bochechas rosadas e barriga amarela.", "Tem um caracol de cabelo enrolado no alto da cabeça, que mostra que é rei."]$j$::jsonb),
(187, $j$["É tão leve que os ventos mais fortes podem levá-lo embora.", "Prende-se ao chão com os pés quando sente que vai ventar demais.", "Pequeno, rosa e redondo, com olhos grandes e pés pequeninos.", "Tem duas folhas verdes saindo da cabeça, como hélices."]$j$::jsonb),
(188, $j$["Gosta de dias quentes e flutua quando a temperatura sobe.", "Abre e fecha o que tem na cabeça para controlar a altura do voo.", "Verde, pequeno e redondo, com olhos grandes e pés curtos.", "Tem uma flor amarela aberta no topo da cabeça que funciona como paraquedas."]$j$::jsonb),
(189, $j$["Viaja com o vento e pode dar voltas inteiras ao mundo.", "Solta sementes pelo caminho enquanto atravessa o céu.", "Azul, pequeno e redondo, com olhos e pezinhos minúsculos.", "Tem três bolas de algodão fofo, uma em cima e duas nos braços."]$j$::jsonb),
(190, $j$["Vive no alto das árvores e passa o dia brincando nos galhos.", "É travesso e esperto, gosta de pegar objetos e fazer bagunça.", "Macaquinho roxo, de orelhas grandes e um sorriso aberto.", "A ponta da cauda é uma mão tão hábil que ele a usa mais que as próprias mãos."]$j$::jsonb),
(191, $j$["Fica parado quase o tempo todo, sem fazer muita coisa.", "Absorve a luz do sol para crescer e evita se mexer para não gastar energia.", "Pequenino, amarelo e em forma de gota, com olhos pretos e duas folhinhas.", "Parece uma semente que cai do céu, especialmente em manhãs de sol."]$j$::jsonb),
(192, $j$["É ativo durante o dia e para de se mexer assim que escurece.", "Transforma a luz em energia e fica cheio de vida quando o tempo está bom.", "Corpo verde de folhas, com pétalas amarelas ao redor do rosto.", "Vira o rosto de flor sempre na direção do sol, como um girassol."]$j$::jsonb),
(193, $j$["É rápido e aparece em matas e lagoas em dias quentes.", "Bate as asas tão rápido que fica parado no ar e corta galhos com o vento.", "Inseto vermelho e verde, de olhos grandes e quatro asas transparentes.", "Seus olhos enormes enxergam em todas as direções sem precisar virar a cabeça, como uma libélula."]$j$::jsonb),
(194, $j$["Vive em águas frias e só sai à noite para procurar comida.", "Quando fica fora da água, cobre o corpo com uma gosma para não secar.", "Pequeno, azul, de olhos pretos, rabo grosso e sorriso permanente.", "Tem ramos rosa na cabeça que parecem guelras de um girino."]$j$::jsonb),
(195, $j$["É desatento e nada sem rumo, sem prestar atenção em nada.", "Bate a cabeça nos barcos e nem percebe, continuando a nadar.", "Azul-escuro, com olhos pequenos e uma expressão sempre distraída.", "Abre a boca e engole a comida sem mastigar, com cara de quem não entendeu nada."]$j$::jsonb),
(196, $j$["É leal a quem o trata com carinho e confia no seu treinador.", "Prevê o próximo movimento do inimigo antes mesmo dele agir.", "Lilás e de quatro patas, com orelhas grandes e uma cauda dividida ao meio.", "Tem uma joia vermelha na testa e evolui com a amizade durante o dia."]$j$::jsonb),
(197, $j$["É noturno e se esconde nas sombras quando ataca.", "Quando se irrita, solta um suor venenoso pelos poros.", "Preto e de quatro patas, com olhos vermelhos e orelhas pontudas.", "Seus anéis amarelos brilham na escuridão, mostrando onde ele está."]$j$::jsonb),
(198, $j$["Dizem que vê-lo à noite traz azar e más notícias.", "Junta objetos brilhantes e os esconde no ninho.", "Ave preta com bico amarelo e penas na cabeça que parecem um chapéu.", "Seu penacho lembra um chapéu de bruxa, e voa como um corvo."]$j$::jsonb),
(199, $j$["É calmo e reflexivo, sempre pensando em algo profundo.", "Ficou muito inteligente depois que algo mordeu sua cabeça.", "Rosa, de pé, com um manto branco e expressão pensativa.", "Usa uma concha na cabeça como coroa, como um rei sábio."]$j$::jsonb),
(200, $j$["Adora pregar peças e assustar as pessoas no meio da noite.", "Se diverte com o medo dos outros e some no escuro sem deixar rastro.", "Corpo flutuante e escuro, com cabelos ondulados e um colar de pérolas vermelhas.", "É um fantasma que grita como um choro para espantar quem passa."]$j$::jsonb),
(201, $j$["Vive escondido em ruínas antigas, longe de olhares curiosos.", "Ninguém sabe ao certo o que ele faz ou de onde veio.", "Existem muitas formas diferentes, cada uma com um olho no centro.", "Parece uma letra do alfabeto e, juntos, formam palavras misteriosas."]$j$::jsonb),
(202, $j$["Prefere ficar quieto no escuro, longe de confusão, e quase nunca toma a iniciativa numa briga.", "Nunca ataca primeiro: espera o golpe do outro e devolve tudo com força parecida.", "Corpo azul e mole, como um saco de pancada, com braços curtinhos e olhos sempre apertados.", "Esconde a todo custo uma cauda preta com olhos; vive batendo continência com a mão na testa."]$j$::jsonb),
(203, $j$["Vive em savanas e campos abertos, pastando com calma e vigiando os arredores.", "Nunca é pego de surpresa por trás: algo nele continua alerta mesmo quando cochila.", "Pescoço comprido, pernas finas e pelagem dividida em duas cores, amarelo na frente e escuro atrás.", "A cauda tem uma segunda cabeça com boca e cérebro pequenos, que morde quem chega por trás."]$j$::jsonb),
(204, $j$["Passa o dia pendurado nos galhos, imóvel, esperando insetos passarem por perto.", "Se alguém sacode a árvore onde ele está, reage com uma explosão para assustar o intruso.", "Pequeno e arredondado, coberto de escamas cinza-esverdeadas, com olhinhos apertados no meio.", "Parece uma pinha viva que estoura como bomba quando incomodada e vai engordando a casca com cascas de árvore."]$j$::jsonb),
(205, $j$["Fica parado no mesmo lugar quase o tempo todo, sem demonstrar pressa nem curiosidade.", "Só se abre um pouquinho na hora de comer, e quem espia lá dentro nunca vê direito.", "Corpo grande, roxo e todo fechado, com placas pesadas que parecem chapas de metal.", "Uma concha de aço cheia de canhões e pontas que se abre só para comer ou disparar."]$j$::jsonb),
(206, $j$["Vive escondido em cavernas e túneis, longe da luz, e foge assim que é visto.", "Quando descoberto, escapa voando baixinho, pertinho do chão, sem nunca subir muito.", "Corpo comprido e gordinho, amarelo com listras azuis, e olhos grandes sem pupila.", "Cauda em forma de broca e asinhas minúsculas que mal conseguem tirar a cobra do chão."]$j$::jsonb),
(207, $j$["Mora em penhascos e espera em silêncio, lá no alto, a hora certa de agir.", "Plana sem fazer barulho e cai sobre a vítima, agarrando o rosto com força.", "Corpo roxo, pernas fininhas e asas de membrana presas aos braços, como um morcego.", "Parece um escorpião voador, com pinças grandes e um ferrão na ponta da cauda."]$j$::jsonb),
(208, $j$["Vive enterrado bem fundo, cavando sem parar em busca de lugares mais quentes e calmos.", "Mastiga pedras ao cavar, e o barulho que faz pode ser ouvido de muito longe.", "Corpo gigante e comprido, formado por blocos cinzentos e brilhantes encaixados um no outro.", "Uma serpente enorme de pedra que, de tanto viver sob pressão, ficou mais dura que diamante."]$j$::jsonb),
(209, $j$["Muito apegado ao dono, adora brincar e sai correndo atrás de quem for simpático com ele.", "Os animais menores costumam fugir dele, mesmo ele sendo um bichinho carinhoso.", "Pequeno, rosado, com orelhas caídas e pernas curtinhas, lembra um cachorrinho de colo.", "Tem cara de buldogue bravo, com dentões para fora, mas é um amor de companhia."]$j$::jsonb),
(210, $j$["Apesar da cara feia, é tímido e assusta-se fácil com barulhos e movimentos bruscos.", "Bichinhos menores fogem ao vê-lo, mas ele só morde de verdade quando é muito provocado.", "Corpo roxo e robusto, braços grossos e um jeito pesado de andar sobre duas pernas.", "Um queixo enorme com dois dentes gigantes para fora deixa a cara dele sempre emburrada."]$j$::jsonb),
(211, $j$["Nada em cardumes no mar e fica nervoso quando outros se aproximam rápido demais.", "Para se defender, enche-se de água e dispara pontas venenosas em todas as direções.", "Pequeno, redondo e cinza-esverdeado, com uma cauda de nadadeira e olhos assustados.", "Um peixe-baiacu que incha feito bola coberto de espinhos tóxicos."]$j$::jsonb),
(212, $j$["Vive treinando o corpo para ficar mais forte e não aguenta ficar parado.", "Usa os braços em golpes rápidos e afiados, e assusta os rivais mostrando as garras.", "Corpo vermelho e reluzente, rígido como metal, com asas pequenas que servem para regular o calor.", "As pinças têm desenhos de olhos que confundem o inimigo; é um louva-a-deus vermelho de aço."]$j$::jsonb),
(213, $j$["Esconde-se debaixo de pedras e fica quietinho por horas, quase sem se mexer.", "Guarda comida dentro de si e ela vira um líquido doce que outros adoram provar.", "Corpo amarelo e mole, com patinhas curtas e cabeça pequena para fora.", "Vive dentro de uma casca vermelha com buracos, onde frutas fermentam e viram suco."]$j$::jsonb),
(214, $j$["Adora a seiva das árvores e passa o dia nas florestas procurando a mais doce.", "Tem uma força absurda e consegue lançar longe adversários muito mais pesados que ele.", "Corpo azul e duro como armadura, braços fortes e asas escondidas sob as costas.", "Um besouro azul com um chifre grande na testa, usado para derrubar e arremessar rivais."]$j$::jsonb),
(215, $j$["Esperto e traiçoeiro, vive em lugares frios e anda em grupo para caçar.", "Rouba ovos de ninhos quando os pais se distraem e marca árvores com arranhões.", "Corpo escuro e esguio, olhos amarelos e uma pena vermelha na orelha.", "Tem garras enormes e afiadas nas patas, prontas para arranhar, numa pose de gato sorrateiro."]$j$::jsonb),
(216, $j$["Fofinho e brincalhão, mas fica desconfiado quando estranhos se aproximam do seu esconderijo.", "Junta comida em vários cantos da floresta e vive procurando favos para encher a barriga.", "Pequeno, marrom e redondinho, com orelhas redondas e um focinho cor de creme.", "Ursinho com uma lua crescente na testa que vive lambendo as patas cheias de mel."]$j$::jsonb),
(217, $j$["Domina a floresta e anda por ela todos os dias, como se fosse o dono do lugar.", "Fareja comida de muito longe e marca as árvores com arranhões fortes para avisar os outros.", "Grande, pesado e marrom, anda de quatro ou fica em pé assustando quem aparece.", "Urso enorme com um anel claro desenhado na barriga e garras poderosas."]$j$::jsonb),
(218, $j$["Vive em lugares muito quentes e nunca para de se mexer, nem quando dorme.", "Se fica muito tempo parado, começa a endurecer, então anda devagar sem parar.", "Pequeno, vermelho-alaranjado e brilhante, com olhos amarelos e corpo que escorre.", "Uma lesma feita de lava derretida, que goteja e deixa um rastro quente por onde passa."]$j$::jsonb),
(219, $j$["Vive perto de vulcões e quase nunca sai das regiões mais quentes.", "É tão quente que a água chia e vira vapor ao encostar nele.", "Corpo vermelho e mole, como lava, que escorre pelo chão com lentidão.", "Uma lesma de magma com uma casca de pedra rachada nas costas, de onde escapam chamas."]$j$::jsonb),
(220, $j$["Adora fuçar o chão gelado e vive em montanhas e cavernas com muita neve.", "Procura cogumelos e raízes com o focinho, e às vezes se empolga e corre sem rumo.", "Pequeno e redondinho, marrom, com um focinho rosado e olhinhos escondidos.", "Um porquinho de pelo grosso com listras nas costas que aguenta o frio mais forte."]$j$::jsonb),
(221, $j$["Vive em montanhas geladas e não se importa com tempestades de neve.", "Não enxerga quase nada e sente o mundo pelo focinho, sensível ao menor cheiro.", "Corpo grande, redondo e marrom, coberto de pelo comprido e desgrenhado.", "Um javali peludo com presas de gelo, cujo pelo cobre totalmente os olhos."]$j$::jsonb),
(222, $j$["Gosta de águas rasas, quentes e limpas, e some quando o mar fica sujo.", "Grupos dele formam um tipo de recife onde outros bichos marinhos se escondem.", "Pequeno, rosado e pontudo, com patinhas curtas e uma base branca.", "Tem galhos de coral na cabeça que quebram fácil, mas crescem de novo."]$j$::jsonb),
(223, $j$["Nada em cardumes e é muito preciso quando mira algo que voa fora d'água.", "Gosta de grudar em peixes maiores para viajar de carona e comer as sobras.", "Pequeno, cinza-azulado, com uma barbatana no topo e olhos grandes.", "Peixe que cospe jatos de água como uma pistola e acerta presas no ar."]$j$::jsonb),
(224, $j$["Prefere viver no fundo do mar, escondido em tocas entre as rochas.", "Quando ameaçado, solta tinta preta para fugir e deixa o inimigo perdido.", "Corpo vermelho, cabeça arredondada e uma boca em forma de canudinho.", "Um polvo vermelho com ventosas nos tentáculos que agarram o oponente com força."]$j$::jsonb),
(225, $j$["Mora em lugares gelados e anda sozinho pelas montanhas cobertas de neve.", "Generoso, carrega comida guardada e a entrega para quem estiver perdido.", "Corpo vermelho e branco, com um bico amarelo e uma pose de quem está sempre ocupado.", "Pássaro que carrega presentes num saco feito com a própria cauda."]$j$::jsonb),
(226, $j$["Nada calmamente em mares quentes, e alguns peixes vivem grudados no corpo dele.", "Às vezes sai da água pulando e plana alguns metros antes de mergulhar de volta.", "Corpo achatado azul-escuro por cima e claro por baixo, com antenas na cabeça.", "Uma arraia gigante com asas enormes que parece voar debaixo d'água."]$j$::jsonb),
(227, $j$["Vive em montanhas e penhascos, onde quase ninguém consegue chegar.", "Suas penas velhas caem e as pessoas usam para fazer facas e espadas.", "Corpo cinza e brilhante, com asas largas e um bico curvo e forte.", "Pássaro de metal com asas que cortam como lâminas e penas vermelhas por dentro."]$j$::jsonb),
(228, $j$["Anda em bando e se comunica com uivos que se ouvem de longe à noite.", "Caça em grupo, cercando a presa com estratégia antes de atacar.", "Corpo escuro e magro, com patas fortes e ossos brancos nas costas.", "Um cão negro com coleira de ossos e um focinho que solta fogo."]$j$::jsonb),
(229, $j$["Chefia o bando e não aceita que nenhum outro tome seu lugar.", "Seu uivo assusta qualquer um, e antigamente diziam que ele trazia azar.", "Corpo negro e magro, com patas longas e costelas brancas nas costas.", "Tem chifres curvos na cabeça e uma cauda que termina em ponta de lança."]$j$::jsonb),
(230, $j$["Dorme no fundo do mar e só acorda quando chega uma tempestade forte.", "Quando nada com força, cria redemoinhos capazes de virar barcos pequenos.", "Corpo azul e longo, com barbatanas amarelas e um focinho comprido.", "Um cavalo-marinho enorme com duas formas de dragão e uma coroa de barbatanas."]$j$::jsonb),
(231, $j$["Brincalhão, adora correr com os amigos e rolar pelo chão de terra.", "Usa a tromba para se refrescar, jogando água no corpo nos dias quentes.", "Pequeno, azul-claro e gordinho, com orelhas grandes e redondas.", "Um elefantinho azul com tromba curta que adora tomar banho de lama."]$j$::jsonb),
(232, $j$["Vive em grupos e fica bravo quando alguém entra no seu território.", "Para atacar, enrola o corpo e rola em alta velocidade, derrubando tudo.", "Corpo cinza e pesado, com uma pele dura como armadura e listras escuras.", "Um elefante blindado com presas grandes que rola feito pneu para atacar."]$j$::jsonb),
(233, $j$["Aprende sozinho coisas novas e foi criado para explorar onde ninguém vai.", "Atualizado por programas, às vezes faz movimentos estranhos que nem foram ensinados.", "Corpo arredondado e liso, vermelho e azul, sem pernas visíveis.", "Um pato digital feito no computador, com corpo de plástico e formas suaves."]$j$::jsonb),
(234, $j$["Vive em florestas e campos, e anda com elegância entre as árvores.", "Seus chifres criam ilusões em quem olha muito tempo, e foram usados como amuletos.", "Corpo marrom e esguio, com pernas finas e uma cauda curtinha.", "Um cervo com chifres curvos e uma esfera que hipnotiza na ponta deles."]$j$::jsonb),
(235, $j$["Deixa marcas em todo lugar por onde passa, como se assinasse o território.", "Cada um tem um estilo próprio e nunca repete o mesmo traço duas vezes.", "Corpo bege e magro, com uma boina na cabeça e olhos calmos.", "Pinta com a ponta da cauda como se fosse um pincel."]$j$::jsonb),
(236, $j$["Treina todos os dias para ficar mais forte e nunca desiste de um desafio.", "Briga com qualquer um, mesmo que seja bem maior, só para aprender.", "Pequeno e roxo, com corpo musculoso e uma faixa na cintura.", "Um lutador mirim que vai virar um de três estilos de luta diferentes."]$j$::jsonb),
(237, $j$["Adora lutar e se diverte rodopiando enquanto acerta os adversários.", "Seus chutes são rápidos e acertam vários lados ao mesmo tempo.", "Corpo marrom e musculoso, com um chifre no topo da cabeça.", "Gira de ponta-cabeça sobre o chifre como um pião, chutando enquanto rodopia."]$j$::jsonb),
(238, $j$["É curiosa e explora tudo à sua volta, sem medo de nada.", "Testa tudo com os lábios para descobrir se gosta ou não.", "Pequena e rosada, com cabelos loiros e um vestidinho roxo.", "Quando gosta de algo, dança e pula de felicidade sem parar."]$j$::jsonb),
(239, $j$["Fica agitado quando o céu escurece e corre animado durante as tempestades.", "Entre seus dois chifres passa uma corrente que dá choque em quem chega perto.", "Pequeno e amarelo com listras pretas, e um rosto meio bravo.", "Tem uma tomada no topo da cabeça e gira os braços para soltar eletricidade."]$j$::jsonb),
(240, $j$["É ativo e brincalhão, e adora ficar perto de coisas quentes.", "Cada vez que respira, solta faíscas de fogo pela boca.", "Pequeno, vermelho e amarelo, com cabeça redonda e corpo baixinho.", "Quando está bem de saúde, as chamas que solta ficam amarelas."]$j$::jsonb),
(241, $j$["Vive em pastos e campos, e anda sempre em grupo com outros parecidos.", "Seu leite é muito nutritivo e faz crianças doentes melhorarem bem rápido.", "Corpo rosado e redondo, com chifres pequenos e manchas pretas.", "Uma vaca rosa que dá leite tão bom que é usado como remédio."]$j$::jsonb),
(242, $j$["Gentil e carinhosa, sente a tristeza dos outros e corre para ajudar.", "O ovo que carrega espalha alegria e acalma qualquer um que o prove.", "Corpo redondo e rosado, com pelinhos brancos parecendo nuvens.", "Uma ave fofa e gordinha com um ovo branco guardado na barriga."]$j$::jsonb),
(243, $j$["Corre pelo mundo e quase ninguém consegue vê-lo de perto.", "Dizem que caiu do céu junto com um raio e espalha trovões por onde passa.", "Corpo amarelo com listras pretas e uma juba roxa que parece nuvem.", "Um tigre de trovão tão veloz que vira um borrão amarelo ao correr."]$j$::jsonb),
(244, $j$["Dizem que nasceu numa erupção e anda pelo mundo como se procurasse algo.", "Quando ruge, a terra treme e os vulcões parecem despertar.", "Corpo marrom e robusto, com uma juba cinzenta que parece fumaça.", "Um leão de fogo com uma placa dourada no rosto que faz os vulcões acordarem."]$j$::jsonb),
(245, $j$["Anda pelo mundo sem parar, como o vento que vem do norte.", "Onde passa, a água suja fica limpa e cristalina de novo.", "Corpo azul-claro com manchas brancas em forma de losango.", "Uma fera azul de juba roxa ondulante que purifica as águas por onde corre."]$j$::jsonb),
(246, $j$["Nasce embaixo da terra e passa muito tempo comendo o solo para crescer.", "Só sai da terra quando já está bem grande e forte.", "Pequeno, verde, com olhos vermelhos e uma barriga clara.", "Tem um chifre na cabeça e um buraco no peito em forma de losango."]$j$::jsonb),
(247, $j$["Fica dentro de uma carapaça e quase não se mexe, guardando energia.", "Quando está pronto para evoluir, solta gás com força e sai voando.", "Corpo cinza e duro, sem braços nem pernas visíveis.", "Um casulo de pedra azul que dispara como foguete soltando gás."]$j$::jsonb),
(248, $j$["É tão forte que derruba montanhas e muda a paisagem quando briga.", "Anda pelos campos procurando um adversário que esteja à sua altura.", "Corpo enorme e verde, com espinhos nas costas e uma cauda grossa.", "Um monstro blindado com um buraco azul no peito, como um dinossauro rei."]$j$::jsonb),
(249, $j$["Dizem que vive escondido no fundo do mar, longe de todos.", "Um bater de suas asas pode causar tempestades que duram vários dias.", "Corpo branco e enorme, com placas azuis nas costas e na barriga.", "Uma ave gigante dos mares com asas que parecem mãos e domina as tempestades."]$j$::jsonb),
(250, $j$["Voa sem parar pelo céu e só aparece para quem tem o coração puro.", "Dizem que quem o vê terá felicidade e sorte para sempre.", "Ave enorme com penas vermelhas, verdes e brancas.", "Suas penas brilham com sete cores diferentes, como um arco-íris."]$j$::jsonb),
(251, $j$["Aparece só em florestas tranquilas e some sem deixar rastro.", "Onde passa, as plantas florescem e a mata fica mais viva.", "Pequeno, verde e delicado, com olhos azuis grandes e asinhas finas.", "Viaja no tempo, parece uma fadinha da floresta com antenas na cabeça."]$j$::jsonb)
insert into public.posts(kind, title, body, created_by)
