-- =====================================================================
-- POKEGAMES — Silhueta travada e Descrição mais difícil (pedido do dono em 30/10/2026).
--
-- 1) Silhueta: antes o servidor mandava a imagem INTEIRA e o site só dava
--    zoom; abrindo a figura em outra página dava para ver tudo. Agora cada
--    Pokémon tem as 7 etapas do zoom já cortadas (silhouette_levels, geradas
--    pelo admin em Administração → Pokédex → "Travar as silhuetas"), e o
--    servidor manda só a etapa em que a pessoa está. A imagem inteira só
--    sai no fim. Vale para o desafio do dia e para o duelo de quiz.
--    Enquanto um Pokémon não tiver as etapas geradas, fica como antes.
-- 2) Descrição: cada Pokémon ganha um verbete de Pokédex mais completo, em
--    4 frases originais, da mais vaga para a mais reveladora. O jogador vê
--    a 1ª; a cada erro, ganha mais uma (como o zoom da silhueta). Só as
--    frases reveladas saem do servidor. Liga/desliga em
--    Administração → Ajustes do jogo → Desafio do dia (desc_progressiva).
-- Antes de rodar à mão, faça a cópia de segurança.
-- =====================================================================

alter table public.pokemon_media add column if not exists silhouette_levels jsonb;   -- 7 imagens: do zoom maior à silhueta inteira
alter table public.pokemon_media add column if not exists description_parts jsonb;   -- 4 frases: da mais vaga à mais reveladora

create or replace function public.desafio_cfg() returns jsonb
language sql stable security definer set search_path = public, extensions as $$
  select '{"desc_progressiva": true}'::jsonb || coalesce(public.cfg()->'desafio', '{}'::jsonb)
$$;

-- o admin grava as etapas cortadas da silhueta (geradas no aparelho dele, a partir da imagem da PokeAPI)
create or replace function public.admin_save_sil_levels(_id int, _levels jsonb) returns void
language plpgsql security definer set search_path = public, extensions as $$
begin
  perform public.assert_admin();
  if jsonb_typeof(_levels) <> 'array' or jsonb_array_length(_levels) <> 7 then raise exception 'São 7 etapas da silhueta.'; end if;
  if exists (select 1 from jsonb_array_elements_text(_levels) x where x not like 'data:image/%' or length(x) > 200000) then raise exception 'Imagem inválida.'; end if;
  on conflict (pokemon_id) do update set silhouette_levels = excluded.silhouette_levels, updated_at = now();
end $$;

-- desafio do dia (versão do 06 + silhueta cortada e descrição em partes)
create or replace function public.puzzle_state(_mode public.puzzle_mode, _date date default null) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare uid uuid := public.assert_active(); d date;
  ans int; a pokemon; s guess_sessions; media pokemon_media; clue jsonb := '{}'::jsonb;
  moved boolean; finished boolean; lvl int; n int; made int; hints jsonb := '[]'::jsonb; last guesses; k int;
begin
  d := case when _date is null or _date = public.game_today() then public.game_today() else public.play_date(_date) end;
  perform public.ensure_puzzles(d);
  select pokemon_id into ans from daily_puzzles where puzzle_date = d and mode = _mode;
  if ans is null then return jsonb_build_object('mode', _mode, 'date', d, 'available', false); end if;
  select * into a from pokemon where id = ans;
  select * into s from guess_sessions where user_id = uid and puzzle_date = d and mode = _mode;
  moved := exists (select 1 from daily_moves where user_id = uid and move_date = d);
  finished := coalesce(s.solved,false) or coalesce(s.failed,false) or moved;
  made := coalesce(s.attempts,0) + coalesce(s.retries_used,0);
  select * into media from pokemon_media where pokemon_id = ans;
  if _mode = 'descricao' then
    -- descrição em partes (arquivo 60): começa vaga e cada erro revela mais uma frase; só as reveladas saem do servidor
    n := coalesce(jsonb_array_length(media.description_parts), 0);
    if n > 0 and coalesce((public.desafio_cfg()->>'desc_progressiva')::boolean, true) then
      k := case when finished then n else least(made + 1, n) end;
      clue := jsonb_build_object('text', (select string_agg(x, ' ' order by o) from jsonb_array_elements_text(media.description_parts) with ordinality t(x, o) where o <= k),
                                 'parts', k, 'parts_total', n);
    elsif n > 0 then
      clue := jsonb_build_object('text', (select string_agg(x, ' ' order by o) from jsonb_array_elements_text(media.description_parts) with ordinality t(x, o)));
    else
      clue := jsonb_build_object('text', media.description);
    end if;
  elsif _mode = 'silhueta' then
    -- silhueta já cortada no zoom de cada etapa (arquivo 60): a imagem inteira só sai do servidor no fim
    n := coalesce(jsonb_array_length(media.silhouette_levels), 0);
    if n > 0 then
      clue := jsonb_build_object('image', media.silhouette_levels->>(case when finished then n - 1 else least(made, n - 1) end), 'zoom_step', made, 'cropped', true);
    else
      clue := jsonb_build_object('image', media.silhouette, 'zoom_step', made);
    end if;
  elsif _mode = 'cartao' then
    n := jsonb_array_length(media.pixel_levels);
    lvl := case when finished then n - 1 else least(made, n - 2) end;
    clue := jsonb_build_object('image', media.pixel_levels->>lvl, 'level', lvl, 'levels', n);
  end if;
  if coalesce(s.hints_used,0) >= 1 then hints := hints || to_jsonb('Tipo principal: ' || a.type1); end if;
  if coalesce(s.hints_used,0) >= 2 then hints := hints || to_jsonb('Habitat: ' || a.habitat); end if;
  if coalesce(s.hints_used,0) >= 3 then hints := hints || to_jsonb('Começa com a letra ' || left(a.name,1)); end if;
  select * into last from guesses where user_id = uid and puzzle_date = d and mode = _mode order by id desc limit 1;
  return jsonb_build_object(
    'mode', _mode, 'date', d, 'available', true, 'recovery', d < public.game_today(),
    'attempts', coalesce(s.attempts,0), 'solved', coalesce(s.solved,false),
    'failed', coalesce(s.failed,false) or (moved and not coalesce(s.solved,false)),
    'finished', finished, 'max_guesses', (cfg()->>'max_guesses')::int,
    'steps', public.mode_steps(coalesce(s.attempts,0), coalesce(s.solved,false)),
    'rank_attempts', case when coalesce(s.solved,false) then public.rank_attempts(s.attempts, true, s.hints_used, s.retries_used) end,
    'hints_used', coalesce(s.hints_used,0), 'retries_used', coalesce(s.retries_used,0),
    'max_hints', (cfg()->>'max_hints_per_mode')::int, 'hints', hints,
    'can_retry', not finished and coalesce(s.retries_used,0) < 1 and last.id is not null and not last.correct and not last.annulled,
    'clue', clue,
    'answer', case when finished then jsonb_build_object('id', a.id, 'name', a.name) end,
    'guesses', coalesce((select jsonb_agg(jsonb_build_object('pokemon_id', pokemon_id, 'correct', correct, 'annulled', annulled, 'feedback', feedback) order by id)
                         from guesses where user_id = uid and puzzle_date = d and mode = _mode), '[]'::jsonb));
end $$;

-- duelo de quiz (versão do 23 + silhueta cortada)
create or replace function public.duel_state(_id uuid) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare uid uuid := public.assert_active(); d duels; side text; mine int; img text; lv jsonb;
begin
  perform public.expire_duels();
  select * into d from duels where id = _id;
  if d.id is null or uid not in (d.challenger, d.opponent) then raise exception 'Duelo não encontrado.'; end if;
  side := case when uid = d.challenger then 'c' else 'o' end;
  -- o cronômetro de cada um começa na primeira vez que abre o duelo aceito
  if d.status = 'aceito' and d.kind = 'quiz' then
    if side = 'c' and d.c_started_at is null and d.c_done_at is null then update duels set c_started_at = now() where id = d.id returning * into d;
    elsif side = 'o' and d.o_started_at is null and d.o_done_at is null then update duels set o_started_at = now() where id = d.id returning * into d; end if;
  end if;
  mine := case side when 'c' then d.c_attempts else d.o_attempts end;
  if d.kind = 'quiz' and d.pokemon_id is not null then
    select silhouette, silhouette_levels into img, lv from pokemon_media where pokemon_id = d.pokemon_id;
    -- silhueta já cortada (arquivo 60): só a etapa do zoom em que a pessoa está
    if coalesce(jsonb_array_length(lv), 0) > 0 then
      img := lv->>(case when d.status = 'concluido' then jsonb_array_length(lv) - 1 else least(mine, jsonb_array_length(lv) - 1) end);
    end if;
  end if;
  return jsonb_build_object('id', d.id, 'kind', d.kind, 'stake_kind', d.stake_kind, 'stake', d.stake, 'status', d.status,
    'challenger', d.challenger, 'opponent', d.opponent, 'expires_at', d.expires_at, 'winner', d.winner, 'result', d.result,
    'max_guesses', (cfg()->>'duel_quiz_max_guesses')::int,
    'me', jsonb_build_object('attempts', mine, 'solved', case side when 'c' then d.c_solved else d.o_solved end,
                             'done', case side when 'c' then d.c_done_at is not null else d.o_done_at is not null end),
    'other_done', case side when 'c' then d.o_done_at is not null else d.c_done_at is not null end,
    'my_seconds', case side when 'c' then extract(epoch from coalesce(d.c_done_at, now()) - d.c_started_at) else extract(epoch from coalesce(d.o_done_at, now()) - d.o_started_at) end,
    'other_seconds', case when d.status = 'concluido' then case side when 'c' then extract(epoch from d.o_done_at - d.o_started_at) else extract(epoch from d.c_done_at - d.c_started_at) end end,
    'other_attempts', case when d.status = 'concluido' then case side when 'c' then d.o_attempts else d.c_attempts end end,
    'clue', case when img is not null then jsonb_build_object('image', img, 'zoom_step', mine, 'cropped', coalesce(jsonb_array_length(lv), 0) > 0) end,
    'answer', case when d.status = 'concluido' and d.pokemon_id is not null then (select jsonb_build_object('id', id, 'name', name) from pokemon where id = d.pokemon_id) end,
    'guesses', coalesce((select jsonb_agg(jsonb_build_object('pokemon_id', pokemon_id, 'correct', correct) order by id) from duel_guesses where duel_id = d.id and user_id = uid), '[]'::jsonb));
end $$;

-- situação das imagens no admin (versão do 01 + etapas da silhueta e descrições novas)
create or replace function public.admin_media_status() returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
begin
  perform public.assert_admin();
  return jsonb_build_object(
    'images', (select count(*) from pokemon_media where silhouette is not null and pixel_levels is not null),
    'descriptions', (select count(*) from pokemon_media where description is not null),
    'sil_levels', (select count(*) from pokemon_media where silhouette_levels is not null),
    'desc_parts', (select count(*) from pokemon_media where description_parts is not null),
    'missing_sil', (select coalesce(jsonb_agg(p.id order by p.id), '[]'::jsonb) from pokemon p
                    left join pokemon_media pm on pm.pokemon_id = p.id where pm.silhouette_levels is null),
    'missing_ids', (select coalesce(jsonb_agg(p.id order by p.id), '[]'::jsonb) from pokemon p
                    left join pokemon_media pm on pm.pokemon_id = p.id
                    where pm.silhouette is null or pm.pixel_levels is null or pm.description is null));
end $$;

-- números para a aba Ajustes do jogo (versão do 59 + Desafio do dia)
create or replace function public.admin_cfg_efetiva() returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
begin
  perform public.assert_admin();
  return jsonb_build_object('treino', public.treino_cfg(), 'pk', public.pk_cfg(), 'casas', public.casas_cfg(), 'itens', public.items_cfg(),
    'war', public.war_cfg(), 'rocket', public.rocket_cfg(), 'desafio', public.desafio_cfg(), 'base', public.cfg());
end $$;

-- descrições novas: 4 frases originais por Pokémon, da mais vaga para a mais reveladora
on conflict (pokemon_id) do update set description_parts = excluded.description_parts, updated_at = now();


-- ---------- permissões ----------
revoke execute on function public.desafio_cfg() from public, anon, authenticated;
revoke execute on function public.admin_save_sil_levels(int, jsonb) from public, anon;
grant execute on function public.admin_save_sil_levels(int, jsonb) to authenticated;

-- ---------- novidade no Jornal, publicada sozinha ----------
select 'novidade', x.title, x.body, coalesce((select user_id from public.user_roles where role = 'admin' order by user_id limit 1), '00000000-0000-0000-0000-000000000000'::uuid)
  from (values ('🔍 Desafio mais difícil: Descrição e Silhueta', 'Os modos Descrição e Silhueta ficaram mais justos e mais difíceis:
• Descrição: cada Pokémon ganhou um verbete de Pokédex completo, em 4 partes. Você começa só com uma pista vaga, e cada erro revela mais um pedaço.
• Silhueta: agora só chega ao seu aparelho o pedaço que está na tela. Nada de abrir a imagem em outra página para ver inteira!
Boa sorte!')) x(title, body)
 where not exists (select 1 from public.posts p where p.title = x.title);
